export function capability_id(reference) {
  return BASE + segments(reference).join(".");
}

/** Read an identity string back as the contract path it names. */
export function capability_ref(identity) {
  const parts = segments(identity);
  if (parts.length === 0) {
    throw new Error("capability identity must name a contract");
  }
  return parts.join(".");
}

